script:
function urlExists(url, callback){
  $.ajax({
    type: 'HEAD',
    url: url,
    success: function(){
      callback(true);
    },
    error: function() {
      callback(false);
    }
  });
}
$(document).ready(function () {
  $('#select-vbm-app').change(function () {
    var val = $(this).val(),
      urls = {
        '1': 'GEN2026'

      };
    if (val > 0) {

		var url='/fileadmin/user_upload/data/candlog/' + urls[val] + '/candlog.pdf';
		urlExists(url, function(exists){
			//do more stuff based on the boolean value of exists
			if(exists){
				window.location.href = url;
			}else{
				 $("#temp").html("There is currently no data available. Please check back later.");
			}
		});

      //window.location.href = 'http:/fileadmin/user_upload/data/candlog/' + urls[val] + '/candlog.pdf';
    }
  });
});
